import argparse,gzip,hashlib,json,subprocess
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--output',required=True);a=p.parse_args()
ref=json.loads(gzip.decompress(Path('docs/heuristic-lifecycle-reference.json.gz').read_bytes()))
exe=Path('build/petri-comparison-checkpoint-build/Release/minera_export.exe');checks=[]
for i,r in enumerate(ref['observations']):
 x=Path(f'build/heuristic-lifecycle-{i}.xes');x.write_text(r['xes'],encoding='utf-8');out=x.with_suffix('.json')
 cmd=[str(exe),str(x),'--heuristic-variant','plusplus','--heuristic-decoration','performance','-o',str(out)]
 if r['business']:cmd+=['--heuristic-business-hours']
 if r['custom']:cmd+=['--heuristic-timestamp-attribute','finished']
 proc=subprocess.run(cmd,capture_output=True,text=True,timeout=30)
 row={'name':r['name'],'exit_code':proc.returncode,'stderr':proc.stderr}
 if proc.returncode==0:
  payload=json.loads(out.read_text());n=payload['heuristics_net'];names=n['activities'] if n['activity_ids_are_local'] else [v['name'] for v in payload['activities']]
  row['actual']={'frequency':sorted([[[names[v['source']],names[v['target']]],v['raw_frequency']] for v in n['relation_statistics'] if v['raw_frequency']]),'wait':sorted([[[names[v['source']],names[v['target']]],v['mean_wait_seconds']] for v in n['relation_statistics'] if v['direct_adjacency_frequency']]),'sojourn':{names[v['activity']]:v['mean_sojourn_seconds'] for v in n['activity_statistics']}}
 if 'expected' in r:
  row['expected']=r['expected'];row['matched']=row.get('actual')==r['expected']
 else:
  row['reference_error']=r['reference_error'];row['matched']=proc.returncode!=0
 checks.append(row)
report={'checks':checks,'native_executable_sha256':hashlib.sha256(exe.read_bytes()).hexdigest()}
Path(a.output).write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')
print(sum(r['matched'] for r in checks),'/',len(checks));print([r['name'] for r in checks if not r['matched']])
